#!/usr/bin/env sage
"""
Verify Q5117's key finding: M† = M₁₆ · Q₂₀₉(θ)/946
Build Mellin adjoint and check the Q₂₀₉(θ) right factor.
"""


# This file was *autogenerated* from the file scratchpad/p27_mellin_v2.sage
from sage.all_cmdline import *   # import sage library

_sage_const_1024 = Integer(1024); _sage_const_2 = Integer(2); _sage_const_5 = Integer(5); _sage_const_4 = Integer(4); _sage_const_7 = Integer(7); _sage_const_3 = Integer(3); _sage_const_9 = Integer(9); _sage_const_946 = Integer(946); _sage_const_6407 = Integer(6407); _sage_const_10860 = Integer(10860); _sage_const_128 = Integer(128); _sage_const_104060 = Integer(104060); _sage_const_6 = Integer(6); _sage_const_1745370 = Integer(1745370); _sage_const_12145238 = Integer(12145238); _sage_const_44886481 = Integer(44886481); _sage_const_92943995 = Integer(92943995); _sage_const_102256019 = Integer(102256019); _sage_const_46709052 = Integer(46709052); _sage_const_16 = Integer(16); _sage_const_3784 = Integer(3784); _sage_const_57792 = Integer(57792); _sage_const_351019 = Integer(351019); _sage_const_1059230 = Integer(1059230); _sage_const_1587211 = Integer(1587211); _sage_const_944620 = Integer(944620); _sage_const_4515 = Integer(4515); _sage_const_5399 = Integer(5399); _sage_const_1 = Integer(1); _sage_const_0 = Integer(0); _sage_const_1677 = Integer(1677); _sage_const_1830 = Integer(1830); _sage_const_2623 = Integer(2623)
from ore_algebra import *

Rn = PolynomialRing(QQ, names=('n',)); (n,) = Rn._first_ngens(1)
Rt = PolynomialRing(QQ, names=('t',)); (t,) = Rt._first_ngens(1)
Qt = Rt.fraction_field()
Dt_alg = OreAlgebra(Qt, names=('Dt',)); (Dt,) = Dt_alg._first_ngens(1)

# P2.7 primitive polynomial coefficients
A_fn = Rn(_sage_const_1024 *(_sage_const_2 *n+_sage_const_5 )**_sage_const_4 *(_sage_const_2 *n+_sage_const_7 )**_sage_const_3 *(_sage_const_2 *n+_sage_const_9 )**_sage_const_3 *(_sage_const_946 *n**_sage_const_2 +_sage_const_6407 *n+_sage_const_10860 ))
B_fn = Rn(_sage_const_128 *(_sage_const_2 *n+_sage_const_7 )**_sage_const_3 *(_sage_const_2 *n+_sage_const_9 )**_sage_const_3 *(_sage_const_104060 *n**_sage_const_6 +_sage_const_1745370 *n**_sage_const_5 +_sage_const_12145238 *n**_sage_const_4 +_sage_const_44886481 *n**_sage_const_3 +_sage_const_92943995 *n**_sage_const_2 +_sage_const_102256019 *n+_sage_const_46709052 ))
C_fn = Rn(_sage_const_16 *(n+_sage_const_3 )**_sage_const_4 *(_sage_const_2 *n+_sage_const_9 )**_sage_const_3 *(_sage_const_3784 *n**_sage_const_5 +_sage_const_57792 *n**_sage_const_4 +_sage_const_351019 *n**_sage_const_3 +_sage_const_1059230 *n**_sage_const_2 +_sage_const_1587211 *n+_sage_const_944620 ))
D_fn = Rn((n+_sage_const_3 )**_sage_const_4 *(n+_sage_const_4 )**_sage_const_6 *(_sage_const_946 *n**_sage_const_2 +_sage_const_4515 *n+_sage_const_5399 ))

Qn = Rn.fraction_field()
A_rec = OreAlgebra(Qn, 'Sn', names=('Sn',)); (Sn,) = A_rec._first_ngens(1)

L_monic = (Sn**_sage_const_3
           - B_fn(n=n+_sage_const_2 )/A_fn(n=n+_sage_const_2 ) * Sn**_sage_const_2
           + C_fn(n=n+_sage_const_1 )/A_fn(n=n+_sage_const_1 ) * Sn
           - D_fn(n=n)/A_fn(n=n))

coeffs_monic = [Qn(L_monic[i]) for i in range(_sage_const_4 )]
den = Rn.one()
for c in coeffs_monic:
    den = lcm(den, Rn(c.denominator()))
nums = [Rn(den * c) for c in coeffs_monic]
g = nums[_sage_const_0 ]
for c in nums[_sage_const_1 :]:
    g = gcd(g, c)
pnums = [c // g for c in nums]

# Build Mellin adjoint: M† = sum_j t^j * p_j(-theta-j-1)
# where theta = t*Dt

# Helper: compute (-theta-j-1)^k as an operator in Dt_alg
# theta = t*Dt
# (-theta-j-1)^k = (-(t*Dt) - j - 1)^k

print("Building Mellin adjoint M† = Σ_j t^j p_j(-θ-j-1)...")

M_dual = Dt_alg.zero()
for j in range(_sage_const_4 ):
    base_op = -(Qt(t) * Dt + QQ(j + _sage_const_1 ))  # -(theta + j + 1) = -theta - j - 1
    # Build p_j(base_op) = sum_k pnums[j][k] * base_op^k
    pj_eval = Dt_alg.zero()
    power = Dt_alg.one()
    for k in range(pnums[j].degree() + _sage_const_1 ):
        c_k = QQ(pnums[j][k])
        if c_k != _sage_const_0 :
            pj_eval += c_k * power
        if k < pnums[j].degree():
            power = power * base_op
    M_dual += Qt(t)**j * pj_eval
    print(f"  j={j} done")

print(f"\nM† order: {M_dual.order()}")

# Check leading coefficient
lc = Rt(M_dual.leading_coefficient().numerator())
print(f"Leading coeff degree: {lc.degree()}")
print(f"Leading coeff factor: {lc.factor()}")

# Now check for Q₂₀₉(θ) right factor
# Q₂₀₉(θ) = 946*θ² - 2623*θ + 1830
# In terms of Dt: θ = t*Dt, θ² = t*Dt*t*Dt = t*(t*Dt+1)*Dt = t²*Dt² + t*Dt
# So Q₂₀₉(θ) = 946*(t²*Dt² + t*Dt) - 2623*(t*Dt) + 1830
#             = 946*t²*Dt² + (946-2623)*t*Dt + 1830
#             = 946*t²*Dt² - 1677*t*Dt + 1830

Q209_theta = _sage_const_946 *Qt(t)**_sage_const_2 *Dt**_sage_const_2  - _sage_const_1677 *Qt(t)*Dt + _sage_const_1830
print(f"\nQ₂₀₉(θ) = {Q209_theta}")
print(f"Q₂₀₉(θ) order: {Q209_theta.order()}")

# Check if Q₂₀₉(θ) right-divides M†
print("\nChecking if Q₂₀₉(θ)/946 right-divides M†...")
Q209_normalized = Qt(t)**_sage_const_2 *Dt**_sage_const_2  - QQ(_sage_const_1677 )/QQ(_sage_const_946 )*Qt(t)*Dt + QQ(_sage_const_1830 )/QQ(_sage_const_946 )
try:
    Q_rem, R_rem = M_dual.quo_rem(Q209_normalized)
    if R_rem == _sage_const_0 :
        print("*** YES — Q₂₀₉(θ)/946 is an exact right factor! ***")
        print(f"M₁₆ = M† / (Q₂₀₉(θ)/946)")
        print(f"M₁₆ order: {Q_rem.order()}")
    else:
        print(f"No — remainder order: {R_rem.order()}")
        # Try with the unnormalized version
        Q_rem2, R_rem2 = M_dual.quo_rem(Q209_theta)
        if R_rem2 == _sage_const_0 :
            print("But Q₂₀₉(θ) (unnormalized) IS a right factor!")
            print(f"Quotient order: {Q_rem2.order()}")
        else:
            print(f"Unnormalized remainder order: {R_rem2.order()}")
except Exception as e:
    print(f"Division error: {e}")
    import traceback
    traceback.print_exc()

# Alternative: try right_factors
print("\n--- Searching for Euler right factors ---")
try:
    rf2 = M_dual.right_factors(order=_sage_const_2 )
    if rf2:
        print(f"Found {len(rf2)} right factor(s) of order 2:")
        for f in rf2:
            print(f"  {f}")
    else:
        print("No Euler right factor of order 2 found by right_factors()")
except Exception as e:
    print(f"right_factors error: {e}")

# Try: verify Q209(theta) kills t^rho for rho = roots of Q209
print("\n--- Verifying Q₂₀₉(θ) has Euler solutions ---")
RX = PolynomialRing(QQ, names=('X',)); (X,) = RX._first_ngens(1)
Q209_poly = _sage_const_946 *X**_sage_const_2  - _sage_const_2623 *X + _sage_const_1830
disc = _sage_const_2623 **_sage_const_2  - _sage_const_4 *_sage_const_946 *_sage_const_1830
print(f"Q₂₀₉ discriminant: {disc}")
print(f"Factor: {ZZ(abs(disc)).factor()}")
rho_roots = Q209_poly.roots(QQbar)
for rt, mult in rho_roots:
    print(f"  ρ = {CC(rt):.10f} (mult {mult})")

print("\nDone.")
